// Exactly-once effect = at-least-once delivery + idempotent consumer.
// The "inbox" set plays the role of a unique constraint on eventId.
const inbox = new Set();
let balance = 100;

function handle(event) {
  if (inbox.has(event.id)) {          // duplicate: skip the side effect
    console.log("skip duplicate", event.id);
    return;
  }
  inbox.add(event.id);                // in a real DB: same transaction as the update
  balance += event.amount;
  console.log("applied", event.id, "balance", balance);
}

// the broker redelivers e1 (at-least-once)
const delivered = [
  { id: "e1", amount: 50 },
  { id: "e2", amount: -30 },
  { id: "e1", amount: 50 },
  { id: "e2", amount: -30 },
];
console.log("deliveries:", delivered.map(e => e.id).join(","));
delivered.forEach(handle);
console.log("final balance", balance, "(expected 120)");

