# Event sourcing: state is a fold over an append-only log.
# Time O(events); snapshots shorten the fold for long streams.
events = [
    {"type": "Deposited", "amount": 100},
    {"type": "Withdrawn", "amount": 30},
    {"type": "Deposited", "amount": 50},
    {"type": "Withdrawn", "amount": 20},
]

def apply(balance, e):
    if e["type"] == "Deposited":
        return balance + e["amount"]
    if e["type"] == "Withdrawn":
        return balance - e["amount"]
    return balance  # unknown event types are ignored (forward compatible)

def replay(log):
    balance = 0
    for e in log:
        balance = apply(balance, e)
    return balance

print("log:", [(e["type"][0], e["amount"]) for e in events])
print("balance now:", replay(events))
print("balance after 2 events (time travel):", replay(events[:2]))
